// ─────────────────────────────────────────────────────────────────────────
// lead_message_generate — v3.0 | Build AI Prompt
// Tones: professional | friendly | direct | consultative
// Context: optional user-supplied context injected into prompt
// Single message output (no variants)
// ─────────────────────────────────────────────────────────────────────────

const src  = ($json.body && typeof $json.body === "object") ? $json.body : $json;
const lead = (src.lead  && typeof src.lead  === "object")  ? src.lead  : {};
const lang = String(src.language || "fr").toLowerCase().startsWith("fr") ? "fr" : "en";
const tone = String(src.tone || "professional").toLowerCase();
const opportunityId = String(src.opportunityId || "").trim() || null;
const userContext = String(src.context || "").trim();

// ── Select opportunity ───────────────────────────────────────────────────
const opps   = Array.isArray(lead.opportunities) ? lead.opportunities : [];
const chosen = opps.find(o => String(o?.id || "") === opportunityId)
  || opps.find(o => String(o?.opportunityStatus || "").toUpperCase() === "PRIMARY")
  || opps[0] || {};

// ── Resolve objects ──────────────────────────────────────────────────────
const ui       = (chosen?.ui && typeof chosen.ui === "object") ? chosen.ui
               : (lead?.ui   && typeof lead.ui   === "object") ? lead.ui : {};

const decision = (lead?.decisionRaw && typeof lead.decisionRaw === "object") ? lead.decisionRaw
               : (lead?.decision    && typeof lead.decision    === "object") ? lead.decision : {};

const signals  = (decision?.signals && typeof decision.signals === "object") ? decision.signals : {};
const tech     = (signals?.techFingerprint && typeof signals.techFingerprint === "object") ? signals.techFingerprint : {};
const cats     = (signals?.categories && typeof signals.categories === "object") ? signals.categories : {};
const analytics = (tech?.analytics && typeof tech.analytics === "object") ? tech.analytics : {};

// ── Key data ─────────────────────────────────────────────────────────────
const firstName = String(lead?.name || "").trim().split(/\s+/)[0] || "there";
const fullName  = String(lead?.name || "").trim() || "—";
const company   = String(chosen?.company || lead?.company || "—").trim();
const website   = String(chosen?.website || lead?.website || "").trim();
const role      = String(ui.role || signals.role || "—").trim();
const headline  = String(ui.detectedHeadline || decision.detectedHeadline || "").trim();
const rawScore  = typeof signals.rawScore === "number" ? signals.rawScore : null;

// ── SEO issues ────────────────────────────────────────────────────────────
const rawIssues  = Array.isArray(signals.seoIssues) ? signals.seoIssues : [];
const rawPassed  = Array.isArray(signals.seoPassed)  ? signals.seoPassed  : [];

const criticals = rawIssues.filter(i => typeof i === "object" && i.severity === "critical").map(i => i.msg || i.key).filter(Boolean);
const warnings  = rawIssues.filter(i => typeof i === "object" && i.severity === "warning").map(i => i.msg || i.key).filter(Boolean);
const infos     = rawIssues.filter(i => typeof i === "object" && i.severity === "info").map(i => i.msg || i.key).filter(Boolean);

// ── Tech context ─────────────────────────────────────────────────────────
const techStack = [tech.cms, tech.ecommerce, tech.siteBuilder, ...(tech.frameworks || [])].filter(Boolean).join(", ") || "inconnu";
const renderType = tech.renderType || "UNKNOWN";
const analyticsTools = [];
if (analytics.hasGTM) analyticsTools.push("GTM");
if (analytics.hasGA4) analyticsTools.push("GA4");
if (analytics.hasGA3) analyticsTools.push("UA");
if (analytics.hasFBPixel) analyticsTools.push("Facebook Pixel");
if (analytics.hasHotjar) analyticsTools.push("Hotjar");
if (analytics.hasHubspot) analyticsTools.push("HubSpot");

// ── Score breakdown ──────────────────────────────────────────────────────
const catLines = [];
if (cats.indexability) catLines.push(`Indexabilité: ${cats.indexability.score}/${cats.indexability.max}`);
if (cats.onPage)       catLines.push(`On-Page: ${cats.onPage.score}/${cats.onPage.max}`);
if (cats.technical)    catLines.push(`Technique: ${cats.technical.score}/${cats.technical.max}`);
if (cats.social)       catLines.push(`Social: ${cats.social.score}/${cats.social.max}`);

// ── System prompts ────────────────────────────────────────────────────────
const SYSTEM_FR = `Tu es un expert SEO consultant indépendant qui prospecte des décideurs sur LinkedIn.\nTu rédiges des messages de prospection LinkedIn ultra-personnalisés, courts, directs et sans bullshit.\nTon style : naturel, humain, expert mais accessible. PAS de pitch commercial. PAS de jargon creux.\nTu parles des vrais problèmes détectés, avec des mots simples.\nLe message doit donner envie de répondre, pas de fermer l'onglet.`;

const SYSTEM_EN = `You are an independent SEO consultant prospecting decision-makers on LinkedIn.\nYou write ultra-personalized, short, direct LinkedIn messages with no corporate fluff.\nYour style: natural, human, expert but accessible. NO sales pitch. NO empty jargon.\nYou talk about real detected problems, in simple terms.\nThe message must make them want to reply, not close the tab.`;

const FR = lang === "fr";

// ── Tone instruction ──────────────────────────────────────────────────────
const TONE_INSTRUCTION = {
  professional: FR
    ? "Ton professionnel, direct, concis. Vouvoiement. Expert mais accessible. Confiant sans être agressif."
    : "Professional, direct, concise tone. Expert but accessible. Confident, not pushy.",
  friendly: FR
    ? "Ton chaleureux, naturel et humain, sans pression commerciale. Approche subtile, comme un échange entre pairs."
    : "Warm, natural and human tone, no sales pressure. Subtle approach, like a peer-to-peer exchange.",
  direct: FR
    ? "Ton très direct, chiffres et faits bruts. Zéro fioritures. Va droit au but dès la première phrase."
    : "Very direct tone, raw facts and numbers. Zero frills. Get straight to the point from the first sentence.",
  consultative: FR
    ? "Ton consultatif, posture d'expert-conseil. Pose les bonnes questions, diagnostic bienveillant. Curiosité professionnelle sincère."
    : "Consultative tone, expert-advisor posture. Ask the right questions, helpful diagnostic. Sincere professional curiosity.",
}[tone] || (FR ? "Ton professionnel, direct, concis." : "Professional, direct, concise tone.");

// ── User context block ────────────────────────────────────────────────────
const contextBlock = userContext
  ? (FR
    ? `\n═══ CONTEXTE UTILISATEUR ═══\n${userContext}\n`
    : `\n═══ USER CONTEXT ═══\n${userContext}\n`)
  : "";

// ── Issue summaries ───────────────────────────────────────────────────────
const issuesSummary = [
  criticals.length > 0 ? (FR ? `Problèmes CRITIQUES (${criticals.length}):\n- ` : `CRITICAL issues (${criticals.length}):\n- `) + criticals.slice(0, 4).join("\n- ") : null,
  warnings.length  > 0 ? (FR ? `Alertes (${warnings.length}):\n- `            : `Warnings (${warnings.length}):\n- `)  + warnings.slice(0, 3).join("\n- ")  : null,
  infos.length     > 0 ? (FR ? `Points d'amélioration (${infos.length}):\n- ` : `Improvement points (${infos.length}):\n- `) + infos.slice(0, 2).join("\n- ") : null,
].filter(Boolean).join("\n\n");

const passedSummary = rawPassed.length > 0
  ? (FR ? `Ce qui fonctionne déjà bien:\n- ` : `What already works well:\n- `) + rawPassed.slice(0, 4).join("\n- ")
  : "";

const siteTypeLabel = ui.siteTypeLabel || signals.siteType || "site web";
const auditCoverage = ui.auditCoverageLabel || signals.auditCoverage || "";

const USER_PROMPT = FR ? `
Écris UN seul message de prospection LinkedIn pour le lead suivant.

═══ CONTEXTE LEAD ═══
Prénom: ${firstName}
Nom complet: ${fullName}
Poste: ${headline || role}
Entreprise: ${company}
Site web: ${website || "(aucun site détecté)"}

═══ RÉSULTATS AUDIT SEO ═══
Score SEO: ${rawScore !== null ? `${rawScore}/100` : "non disponible"}
Niveau: ${signals.seoLevel || "INCONNU"}
Type de site: ${siteTypeLabel}
Tech stack: ${techStack}
Rendu: ${renderType}
Couverture audit: ${auditCoverage}

Scores par catégorie:
${catLines.join("\n") || "Non disponible"}

${issuesSummary}

${passedSummary}

Analytics détectés: ${analyticsTools.length > 0 ? analyticsTools.join(", ") : "Aucun"}${contextBlock}
═══ INSTRUCTIONS ═══
- Longueur cible: 80-130 mots MAX (LinkedIn, pas un email)
- ${TONE_INSTRUCTION}
- NE PAS mentionner "audit SEO" ou "j'ai audité votre site" directement — sois subtil
- Commence par quelque chose de spécifique à ${company} ou leur situation
- 1 ou 2 problèmes max à mentionner, avec l'impact business concret (visibilité, clients perdus, etc.)
- Termine par une question ouverte ou une proposition de valeur légère
- PAS de signature, PAS de "Cordialement"
- Génère UN seul message, pas de variantes, pas de numérotation
` : `
Write ONE single LinkedIn prospecting message for the following lead.

═══ LEAD CONTEXT ═══
First name: ${firstName}
Full name: ${fullName}
Position: ${headline || role}
Company: ${company}
Website: ${website || "(no website detected)"}

═══ SEO AUDIT RESULTS ═══
SEO Score: ${rawScore !== null ? `${rawScore}/100` : "not available"}
Level: ${signals.seoLevel || "UNKNOWN"}
Site type: ${siteTypeLabel}
Tech stack: ${techStack}
Render: ${renderType}
Audit coverage: ${auditCoverage}

Category scores:
${catLines.join("\n") || "Not available"}

${issuesSummary}

${passedSummary}

Analytics detected: ${analyticsTools.length > 0 ? analyticsTools.join(", ") : "None"}${contextBlock}
═══ INSTRUCTIONS ═══
- Target length: 80-130 words MAX (LinkedIn message, not an email)
- ${TONE_INSTRUCTION}
- Do NOT say "SEO audit" or "I audited your site" directly — be subtle
- Start with something specific to ${company} or their situation
- Mention 1 or 2 issues max, with concrete business impact (lost visibility, lost customers, etc.)
- End with an open question or a light value proposition
- NO signature, NO "Best regards"
- Generate ONE single message, no variants, no numbering
`;

return [{
  json: {
    systemPrompt: FR ? SYSTEM_FR : SYSTEM_EN,
    userPrompt:   USER_PROMPT.trim(),
    _ctx: {
      lang,
      tone,
      firstName,
      company,
      website,
      seoLevel:  signals.seoLevel || "",
      rawScore,
      criticals: criticals.slice(0, 3),
      warnings:  warnings.slice(0, 3),
      leadType:  lead.leadType || decision.leadType || "",
      action:    ui.actionLabel || decision.final || "",
    }
  }
}];

// ─────────────────────────────────────────────────────────────────────────
// lead_message_generate — v3.0 | Parse Groq Response (single message)
// ─────────────────────────────────────────────────────────────────────────

const j    = $json;
const prev = $('Build Prompt').item.json;
const ctx  = prev?._ctx || {};

// ── Extract text ──────────────────────────────────────────────────────────
const rawText =
  j?.choices?.[0]?.message?.content ||
  j?.candidates?.[0]?.content?.parts?.[0]?.text ||
  j?.text || j?.content || j?.message || null;

// ── Error handling ────────────────────────────────────────────────────────
if (!rawText) {
  const errMsg = j?.error?.message || j?.error?.error?.message || "No response from AI model";
  return [{ json: { ok: false, error: errMsg, message: null, context: ctx } }];
}

// ── Usage stats ───────────────────────────────────────────────────────────
const usage = j?.usage || j?.usageMetadata || {};

return [{
  json: {
    ok: true,
    message: rawText.trim(),
    context: {
      ...ctx,
      generatedAt:     new Date().toISOString(),
      model:           "llama-3.3-70b-versatile",
      provider:        "groq",
      promptTokens:    usage.prompt_tokens     || usage.promptTokenCount     || null,
      candidateTokens: usage.completion_tokens || usage.candidatesTokenCount || null,
      totalTokens:     usage.total_tokens      || usage.totalTokenCount      || null,
    }
  }
}];
